 */
bool test_batch_operations() {
    // Step 1: Create observer nodes
    auto node1 = std::make_shared<reaction::ObserverNode>();
    auto node2 = std::make_shared<reaction::ObserverNode>();
    auto node3 = std::make_shared<reaction::ObserverNode>();

    // Step 2: Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // Add nodes to the graph
    graph.addNode(node1);
    graph.addNode(node2);
    graph.addNode(node3);

    // Step 3: Create batch ID
    const void* batchId = static_cast<const void*>(new int(42)); // Unique batch identifier

    // Step 4: Register nodes to batch
    reaction::NodeSet nodeSet;
    nodeSet.insert(node1);
    nodeSet.insert(node2);
    nodeSet.insert(node3);

    graph.registerActiveBatch(batchId, nodeSet);

    // Step 5: Verify nodes are in batch
    bool allNodesInBatch = true;
    if (!graph.isNodeInActiveBatch(node1)) {
        allNodesInBatch = false;
    }
    if (!graph.isNodeInActiveBatch(node2)) {
        allNodesInBatch = false;
    }
    if (!graph.isNodeInActiveBatch(node3)) {
        allNodesInBatch = false;
    }

    if (!allNodesInBatch) {
        delete static_cast<const int*>(batchId);
        return false;
    }

    // Step 6: Unregister batch
    graph.unregisterActiveBatch(batchId);

    // Step 7: Verify nodes are no longer in batch
    bool allNodesNotInBatch = true;
    if (graph.isNodeInActiveBatch(node1)) {
        allNodesNotInBatch = false;
    }
    if (graph.isNodeInActiveBatch(node2)) {
        allNodesNotInBatch = false;
    }
    if (graph.isNodeInActiveBatch(node3)) {
        allNodesNotInBatch = false;
    }

    // Clean up batch ID
