    // Add nodes to the graph
    graph.addNode(nodeA);
    graph.addNode(nodeB);
    graph.addNode(nodeC);

    // Set names for debugging
    graph.setName(nodeA, "NodeA");
    graph.setName(nodeB, "NodeB");
    graph.setName(nodeC, nodeName);

