                                               int initialB,
                                               int nonBatchA,
                                               int nonBatchB,
                                               int batchA,
                                               int batchB) {
    // Step 1: Create reactive variables
    auto a = reaction::var(initialA).setName("a");
    auto b = reaction::var(initialB).setName("b");

    // Step 2: Create variable to track recomputation count
    int recomputeCount = 0;

    // Step 3: Create calculation that depends on both a and b
    auto sum = reaction::calc([&]() {
        ++recomputeCount;
        return a() + b();
    }).setName("sum");

    // Reset counter after initial computation
    recomputeCount = 0;

    // Step 4: Perform non-batch updates
    // Each update will trigger a recomputation of sum
    a.value(nonBatchA);
    b.value(nonBatchB);

    // Step 5: Record recompute count after non-batch updates
    int countAfterNonBatch = recomputeCount;

    // Reset counter for batch operations
    recomputeCount = 0;

    // Step 6-7: Create batch context and execute batch
    // Both updates will be batched, triggering only one recomputation
    reaction::batchExecute([&]() {
        a.value(batchA);
        b.value(batchB);
    });

    // Step 8: Record recompute count after batch updates
    int countAfterBatch = recomputeCount;

    // Step 9: Return final sum and counts
    return std::make_tuple(sum.get(), countAfterNonBatch, countAfterBatch);
}

}  // namespace test_reaction
```

