    // Step 6: Close the source node
    sourceVar.close();

    // Step 7: Get the result after source close
    // With LastHandle policy, the calculation should preserve the last known value
    // even after the source is closed
    int afterSourceClose = calculation.get();

    // Step 8: Return last handle snapshot
    return LastHandleSnapshot{
        .initialValue = initial,
        .afterUpdate = afterUpdate,
        .afterSourceClose = afterSourceClose
    };
}

