inline StackAllocationSnapshot test_stack_monitor_capacity(std::size_t largeSize) {
    using namespace reaction::memory;

    StackAllocationSnapshot snapshot{};

    // 1. Disable monitoring
    StackMonitor::setMonitoringEnabled(false);

    // 2. Initialize stack monitor
    StackMonitor::initialize();

    // 3. Check allocation without monitoring
    // With monitoring disabled, canAllocate checks against CONDITIONAL_SBO_SIZE (32)
    constexpr std::size_t smallSize = 16;  // <= CONDITIONAL_SBO_SIZE
    constexpr std::size_t largeTestSize = 64;  // > CONDITIONAL_SBO_SIZE

    snapshot.smallAllowedWithoutMonitoring = StackMonitor::canAllocate<smallSize>();
    snapshot.largeAllowedWithoutMonitoring = StackMonitor::canAllocate<largeTestSize>();
    snapshot.runtimeAllowedWithoutMonitoring = StackMonitor::canAllocate(smallSize);

    // 4. Enable monitoring
    StackMonitor::setMonitoringEnabled(true);

    // 5. Initialize stack monitor again
    StackMonitor::initialize();

    // 6. Check large allocation with monitoring
    // With monitoring enabled, canAllocate checks against MAX_SBO_STACK_USAGE (64KB)
    snapshot.largeAllowedWithMonitoring = StackMonitor::canAllocate<largeTestSize>();

    // 7. Create StackGuard in scope block
    {
        // Allocate enough to reach the limit (MAX_SBO_STACK_USAGE = 64KB)
        constexpr std::size_t limitSize = SBOConfig::MAX_SBO_STACK_USAGE;
        StackMonitor::StackGuard<limitSize> guard;

        // 8. Check if guard succeeded
        snapshot.guardSucceeded = guard.success();

        // 9. Check if allocation blocked at limit
        // Try to allocate more - should fail since we're at the limit
        snapshot.allocationBlockedAtLimit = !StackMonitor::canAllocate<smallSize>();

        // 10. Exit guard scope (destructor will release the allocation)
    }

    // 11. Check runtime allocation after release
    // After guard scope exits, the stack usage should be released
    snapshot.runtimeAllowedAfterRelease = StackMonitor::canAllocate(largeSize);

    // 12. Return stack allocation snapshot
    return snapshot;
}

}  // namespace test_reaction
