#pragma once

#include <reaction/memory/memory_config.h>
#include <reaction/memory/stack_monitor.h>

namespace test_reaction {

struct StackLimitSnapshot {
    reaction::memory::StackMonitor::UsageStats statsBeforeGuard;
    reaction::memory::StackMonitor::UsageStats statsAfterGuard;
    bool templateAllocationAllowed;
    bool runtimeAllocationAllowed;
    bool guardHeld;
    bool allocationBlockedWhileGuardHeld;
};

StackLimitSnapshot test_stack_monitor_limits() {
    using namespace reaction::memory;

    // 1. Enable monitoring
    StackMonitor::setMonitoringEnabled(true);

    // 2. Initialize stack monitor
    StackMonitor::initialize();

    // 3. Get usage statistics before guard
    auto statsBeforeGuard = StackMonitor::getStats();

    // 4. Check if template allocation is allowed
    constexpr size_t LARGE_SIZE = 8 * 1024; // 8KB allocation
    bool templateAllocationAllowed = StackMonitor::canAllocate<LARGE_SIZE>();

    // 5. Check if runtime allocation is allowed
    bool runtimeAllocationAllowed = StackMonitor::canAllocate(LARGE_SIZE);

    // 6. Create large StackGuard instance
    StackMonitor::StackGuard<LARGE_SIZE> guard;

    // 7. Check if guard succeeded
    bool guardHeld = guard.success();

    // 8. Check if allocation blocked while guard is held
    // Try to allocate more than remaining space (should fail if guard succeeded)
    bool allocationBlockedWhileGuardHeld = false;
    if (guardHeld) {
        // Try to allocate enough to exceed the limit
        constexpr size_t ADDITIONAL_SIZE = SBOConfig::MAX_SBO_STACK_USAGE - LARGE_SIZE + 1;
        allocationBlockedWhileGuardHeld = !StackMonitor::canAllocate<ADDITIONAL_SIZE>();
    }

    // 9. Get usage statistics after guard
    auto statsAfterGuard = StackMonitor::getStats();

    // 10. Return stack limit snapshot
    return StackLimitSnapshot{
        .statsBeforeGuard = statsBeforeGuard,
        .statsAfterGuard = statsAfterGuard,
        .templateAllocationAllowed = templateAllocationAllowed,
        .runtimeAllocationAllowed = runtimeAllocationAllowed,
        .guardHeld = guardHeld,
        .allocationBlockedWhileGuardHeld = allocationBlockedWhileGuardHeld
    };
}

}  // namespace test_reaction
```

## Explanation

This implementation follows all 10 steps you specified:

1. **Enable monitoring**: Uses `StackMonitor::setMonitoringEnabled(true)` to enable stack monitoring for the current thread.

2. **Initialize stack monitor**: Calls `StackMonitor::initialize()` to reset the usage counter to 0.

3. **Get usage statistics before guard**: Captures the initial state using `StackMonitor::getStats()`.

4. **Check if template allocation is allowed**: Uses the compile-time template version `canAllocate<LARGE_SIZE>()` to check if an 8KB allocation would be allowed.

5. **Check if runtime allocation is allowed**: Uses the runtime version `canAllocate(LARGE_SIZE)` to check the same allocation.

6. **Create large StackGuard instance**: Creates a `StackGuard<LARGE_SIZE>` which attempts to reserve 8KB of stack space.

7. **Check if guard succeeded**: Uses `guard.success()` to determine if the allocation was successful.

8. **Check if allocation blocked while guard is held**: If the guard succeeded, it tries to allocate additional space that would exceed the maximum limit (`MAX_SBO_STACK_USAGE` which is 64KB). This should fail, proving that the guard is properly tracking usage.

9. **Get usage statistics after guard**: Captures the state after the guard is created to show the increased usage.

10. **Return stack limit snapshot**: Returns all the collected information in a `StackLimitSnapshot` structure using designated initializers.

The function demonstrates the stack monitoring system's ability to:
- Track stack usage across allocations
- Prevent stack overflow by rejecting allocations that would exceed limits
- Provide detailed usage statistics for debugging

